// Generated 3D AR Garment Texture & Card Image Assets (100% Offline & Matching)
export const GARMENT_AR_TEXTURES: Record<string, string> = {
  'prod-7': 'data:image/png;base64,',
  'prod-8': 'data:image/png;base64,',
  'prod-4': 'data:image/png;base64,',
};

export const GARMENT_CARD_IMAGES: Record<string, string> = {
  'prod-7': 'data:image/jpeg;base64,',
  'prod-8': 'data:image/jpeg;base64,',
  'prod-4': 'data:image/jpeg;base64,',
};

export const getArGarmentTexture = (productId: string): string => {
  return GARMENT_AR_TEXTURES[productId] || "";
};

export const getGarmentCardImage = (productId: string): string | undefined => {
  return GARMENT_CARD_IMAGES[productId];
};
